import itertools

N = 101

def count_solutions():
    count = 0

    # Iterate over possible values for d1, d2, d3, d4, d5 such that sum is 101 and all >= 1.
    # Since d_i >= 1, the maximum value for any d_i is 101 - 4 = 97.

    for d1 in range(1, N - 3):
        for d2 in range(1, N - d1 - 2):
            # Constraint 4: d1 + d2 >= 51
            if d1 + d2 < 51:
                continue

            for d3 in range(1, N - d1 - d2 - 1):
                # Constraint 5: d2 + d3 <= 50
                if d2 + d3 > 50:
                    continue

                for d4 in range(1, N - d1 - d2 - d3):
                    # Constraint 6: d3 + d4 <= 50
                    if d3 + d4 > 50:
                        continue

                    # Calculate d5
                    d5 = N - d1 - d2 - d3 - d4

                    # d5 >= 1 is guaranteed by the loop bounds on d4, but we check for safety
                    if d5 < 1:
                        continue

                    # Constraint 7: d4 + d5 <= 50
                    if d4 + d5 > 50:
                        continue

                    # Constraint 3: d5 + d1 >= 51
                    if d5 + d1 < 51:
                        continue

                    # All constraints satisfied
                    count += 1
    return count

result = count_solutions()
print(result)

