def solve_configuration_1(N=101):
    count = 0
    # We iterate over s1, s2, s3, s4, and derive s5 = N - (s1+s2+s3+s4).
    # All si must be >= 1.

    for s1 in range(1, N - 3):
        for s2 in range(1, N - 3 - s1):
            # Constraint 4: s1 + s2 <= 50 (i.e., s1+s2 <= N/2 - 1/2)
            if s1 + s2 > 50:
                continue

            for s3 in range(1, N - 3 - s1 - s2):
                # Constraint 3: s2 + s3 >= 51
                if s2 + s3 < 51:
                    continue

                # Constraint 5: s3 + s4 <= 50
                # This implies s4 <= 50 - s3. Since s4 >= 1, we must have s3 <= 49.
                if s3 > 49:
                    continue

                for s4 in range(1, N - 2 - s1 - s2 - s3):
                    if s3 + s4 > 50:
                        continue

                    s5 = N - (s1 + s2 + s3 + s4)

                    # Constraint 1 check for s5
                    if s5 < 1:
                        continue

                    # Constraint 2: s5 + s1 >= 51
                    if s5 + s1 < 51:
                        continue

                    # Constraint 6: s4 + s5 <= 50
                    if s4 + s5 > 50:
                        continue

                    # If all constraints are met
                    count += 1

    return count

